// The worker: does the slow network jobs (an HTTPS request takes 0.3 to 10 s) in its own FreeRTOS
// task, one at a time, so loop() keeps animating the screen meanwhile.
//
// loop() hands over one job with everything it needs (submit). The worker runs it and publishes
// the outcome with a new version number; loop() copies the outcome when the version changes.
// The two only meet inside the mutex, and never share a String while the other is using it.
#pragma once

#include <Preferences.h>

#include <mutex>

#include "oracle.h"
#include "weather.h"

struct RequestStats {
  const char *what = "";  // "weather", "ai", ...
  int status = 0;
  uint32_t ms = 0;
  size_t bytes = 0;
};

class Worker {
 public:
  enum class Job : uint8_t { None, Geocode, Weather, Oracle, Ask };

  struct Request {
    Job job = Job::None;
    String text;     // city name, or the question
    Place place;     // for Weather
    String aiUrl, apiKey, model, context;  // for Oracle and Ask
  };

  struct Outcome {
    uint32_t version = 0;
    const char *busy = nullptr;  // what is running right now, nullptr when idle
    Place place;
    bool placeChanged = false;   // a geocode found a new place (loop saves it and fetches weather)
    Weather weather;
    uint32_t weatherAt = 0;      // millis() when it arrived, 0 = never
    OracleAnswer answer;
    String question;             // empty = haiku
    uint32_t answerAt = 0;
    RequestStats last;
    String error;                // last failure, cleared by the next success
  };

  void begin() { xTaskCreatePinnedToCore(task, "worker", 16 * 1024, this, 1, nullptr, 0); }

  // From loop(). false when a job is already waiting or running: one thing at a time.
  bool submit(const Request &r) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (pending_.job != Job::None || out_.busy) return false;
    pending_ = r;
    return true;
  }

  // From loop(): copy the outcome into `mine` if it changed since the last copy.
  bool update(Outcome &mine) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (mine.version == out_.version) return false;
    mine = out_;
    out_.placeChanged = false;  // delivered once
    return true;
  }

 private:
  static void task(void *self) { static_cast<Worker *>(self)->run(); }

  void run() {
    for (;;) {
      Request r;
      {
        std::lock_guard<std::mutex> lock(mutex_);
        if (pending_.job != Job::None) {
          r = pending_;
          pending_ = Request{};
          out_.busy = r.job == Job::Geocode ? "finding place" : r.job == Job::Weather ? "weather" : "asking the ai";
          out_.version++;
        }
      }
      if (r.job == Job::None) {
        vTaskDelay(pdMS_TO_TICKS(50));
        continue;
      }
      perform(r);
    }
  }

  void perform(const Request &r) {
    HttpsResult res;
    Place place;
    Weather weather;
    OracleAnswer answer;
    const char *what = "";
    switch (r.job) {
      case Job::Geocode: what = "geocoding", res = weather::geocode(r.text, place); break;
      case Job::Weather: what = "weather", res = weather::fetch(r.place, weather); break;
      case Job::Oracle:
      case Job::Ask: what = "ai", res = oracle::ask(r.aiUrl, r.apiKey, r.model, r.context, r.job == Job::Ask ? r.text : "", answer); break;
      case Job::None: break;
    }
    const bool good = res.ok() && res.error.isEmpty();
    if (good) log_i("%s: HTTP %d in %lu ms, %u bytes", what, res.status, static_cast<unsigned long>(res.ms), unsigned(res.bytes));
    else log_w("%s failed after %lu ms: %s", what, static_cast<unsigned long>(res.ms), res.error.c_str());

    std::lock_guard<std::mutex> lock(mutex_);
    out_.busy = nullptr;
    out_.last = {what, res.status, res.ms, res.bytes};
    if (!good) {
      out_.error = String(what) + ": " + res.error;
    } else {
      out_.error = "";
      if (r.job == Job::Geocode) out_.place = place, out_.placeChanged = true;
      if (r.job == Job::Weather) out_.weather = weather, out_.weatherAt = millis();
      if (r.job == Job::Oracle || r.job == Job::Ask) {
        out_.answer = answer;
        out_.question = r.job == Job::Ask ? r.text : "";
        out_.answerAt = millis();
      }
    }
    out_.version++;
  }

  std::mutex mutex_;
  Request pending_;
  Outcome out_;
};

// The Bench Oracle: the board asks an AI model about this moment at the bench.
//
// The board talks to a LiteLLM gateway (esp32-labs/apps/ai-gateway, on your Mac or a server) in the
// OpenAI-style chat completions format. LiteLLM forwards to whichever provider and model the name
// maps to (Claude, GPT, Gemini, a local Ollama model...), so switching models never needs a reflash,
// and the provider keys stay on the gateway, not on the chip.
//
// The board sends what it knows (place, time, weather, its own temperature and signal) and asks for
// a haiku, or an answer to your question. To get an answer the screen can draw, the request offers
// one function, show_on_bench, and forces the model to call it: the reply is then always JSON in
// that function's shape (title, lines, LED colour, scene), never free text to pick apart.
//
// The gateway's key lives in NVS on the chip (serial: ai key ...), never in code, git or the log.
#pragma once

#include <ArduinoJson.h>

#include "https_client.h"
#include "weather.h"

struct OracleAnswer {
  String title;       // one or two words
  String lines[4];
  int lineCount = 0;
  uint8_t r = 0, g = 0, b = 0;  // LED colour
  Scene scene = Scene::Clouds;
  String model;
  uint32_t inputTokens = 0, outputTokens = 0;
  uint32_t ms = 0;  // how long the whole request took
};

namespace oracle {

constexpr const char *kDefaultModel = "oracle";  // a model_name in ai-gateway/config.yaml

// The screen fonts only have plain ASCII. Fold the usual typography to it, drop the rest.
inline String toAscii(const char *utf8) {
  String out;
  const auto *s = reinterpret_cast<const uint8_t *>(utf8);
  while (*s) {
    uint32_t cp = *s;
    int extra = cp >= 0xF0 ? 3 : cp >= 0xE0 ? 2 : cp >= 0xC0 ? 1 : 0;
    if (extra) cp &= 0x3F >> extra;
    s++;
    for (; extra > 0 && (*s & 0xC0) == 0x80; extra--, s++) cp = (cp << 6) | (*s & 0x3F);
    if (cp >= 0x20 && cp < 0x7F) out += char(cp);
    else if (cp == 0x2018 || cp == 0x2019) out += '\'';
    else if (cp == 0x201C || cp == 0x201D) out += '"';
    else if (cp == 0x2013 || cp == 0x2014) out += '-';
    else if (cp == 0x2026) out += "...";
    else if (cp == 0xB0) out += " deg";
    else if (cp == 0xDF) out += "ss";
    else if (cp >= 0xE0 && cp <= 0xE5) out += 'a';
    else if (cp >= 0xE8 && cp <= 0xEB) out += 'e';
    else if (cp >= 0xEC && cp <= 0xEF) out += 'i';
    else if (cp >= 0xF2 && cp <= 0xF6) out += 'o';
    else if (cp >= 0xF9 && cp <= 0xFC) out += 'u';
  }
  return out;
}

inline void addTool(JsonDocument &req) {
  JsonObject tool = req["tools"].add<JsonObject>();
  tool["type"] = "function";
  JsonObject fn = tool["function"].to<JsonObject>();
  fn["name"] = "show_on_bench";
  fn["description"] = "Show text on the bench's small 320x170 screen and set its RGB LED.";
  JsonObject schema = fn["parameters"].to<JsonObject>();
  schema["type"] = "object";
  JsonObject props = schema["properties"].to<JsonObject>();
  props["title"]["type"] = "string";
  props["title"]["description"] = "one or two words, at most 14 characters";
  props["lines"]["type"] = "array";
  props["lines"]["items"]["type"] = "string";
  props["lines"]["description"] = "1 to 4 lines, at most 28 characters each, plain ASCII only";
  props["color"]["type"] = "string";
  props["color"]["description"] = "LED colour matching the mood, as #rrggbb";
  props["scene"]["type"] = "string";
  JsonArray scenes = props["scene"]["enum"].to<JsonArray>();
  for (int i = 0; i <= static_cast<int>(Scene::Night); i++) scenes.add(weather::sceneName(static_cast<Scene>(i)));
  JsonArray required = schema["required"].to<JsonArray>();
  for (const char *k : {"title", "lines", "color", "scene"}) required.add(k);
  req["tool_choice"]["type"] = "function";  // must answer by calling it
  req["tool_choice"]["function"]["name"] = "show_on_bench";
}

// context: a small JSON text describing the moment (see main.cpp). question: empty = haiku.
// baseUrl: the gateway, e.g. http://192.168.178.31:4000 (serial: ai url ...).
inline HttpsResult ask(const String &baseUrl, const String &apiKey, const String &model, const String &context,
                       const String &question, OracleAnswer &out) {
  JsonDocument req;
  req["model"] = model;
  req["max_tokens"] = 400;
  JsonArray messages = req["messages"].to<JsonArray>();
  JsonObject system = messages.add<JsonObject>();
  system["role"] = "system";
  system["content"] =
      "You are the Bench Oracle, living inside an ESP32 on a maker's workbench with a tiny screen and an RGB LED. "
      "Be warm, witty and concrete; use the context (place, time, weather, the chip's own state) when it fits. "
      "Always answer by calling show_on_bench. Lines must be short enough for the screen.";
  addTool(req);
  JsonObject msg = messages.add<JsonObject>();
  msg["role"] = "user";
  const String task = question.isEmpty()
                         ? String("Write a haiku (3 lines) about this exact moment at the bench, weaving in the "
                                  "weather. Title: the mood in one or two words.")
                         : "Question from the maker: " + question +
                               "\nAnswer in at most 4 short lines. Title: a one or two word headline.";
  msg["content"] = "Context: " + context + "\n" + task;
  String body;
  serializeJson(req, body);

  String base = baseUrl;
  while (base.endsWith("/")) base.remove(base.length() - 1);
  HttpsResult r = https::post(base + "/v1/chat/completions", body,
                              {{"Authorization", "Bearer " + apiKey}, {"Content-Type", "application/json"}}, 30'000);
  JsonDocument doc;
  const DeserializationError parseError = deserializeJson(doc, r.body);
  if (!r.ok()) {
    // LiteLLM explains errors as {"error":{"message":...,"type":...,"code":...}}
    if (!parseError && doc["error"]["message"].is<const char *>())
      r.error = "HTTP " + String(r.status) + ": " + toAscii(doc["error"]["message"].as<const char *>());
    return r;
  }
  if (parseError) {
    r.error = String("bad JSON: ") + parseError.c_str();
    return r;
  }
  // The function's arguments arrive as a JSON *string* inside the JSON answer: parse it a second time.
  const char *arguments = doc["choices"][0]["message"]["tool_calls"][0]["function"]["arguments"] | "";
  JsonDocument args;
  if (!*arguments || deserializeJson(args, arguments)) {
    r.error = "no show_on_bench call in the reply (does this model support tools?)";
    return r;
  }
  JsonObjectConst input = args.as<JsonObjectConst>();
  OracleAnswer a;
  a.title = toAscii(input["title"] | "");
  for (JsonVariantConst line : input["lines"].as<JsonArrayConst>())
    if (a.lineCount < 4) a.lines[a.lineCount++] = toAscii(line | "");
  unsigned rgb = 0x40C0FF;
  sscanf(input["color"] | "#40c0ff", "#%6x", &rgb);
  a.r = rgb >> 16, a.g = (rgb >> 8) & 0xFF, a.b = rgb & 0xFF;
  if (!weather::sceneFromName(input["scene"] | "", a.scene)) a.scene = Scene::Clouds;
  a.model = doc["model"] | model.c_str();
  a.inputTokens = doc["usage"]["prompt_tokens"] | 0;
  a.outputTokens = doc["usage"]["completion_tokens"] | 0;
  a.ms = r.ms;
  out = a;
  return r;
}

}  // namespace oracle

// Weather from Open-Meteo (https://open-meteo.com): free, no account, no key, JSON over HTTPS.
//   geocode("Hamburg")  -> Place   city name to coordinates (Open-Meteo's geocoding API)
//   fetch(place)        -> Weather now + next 24 hours + 7 days, in one request
// Both block (call them from the worker task) and only fill the result when everything parsed.
#pragma once

#include <ArduinoJson.h>

#include "https_client.h"

struct Place {
  String name;  // "Hamburg, Germany"
  float lat = 0, lon = 0;
  bool valid() const { return !name.isEmpty(); }
};

// What the screen and the oracle need; everything else in the answer is dropped while parsing.
struct Weather {
  static constexpr int kHours = 24, kDays = 7;
  float temp = 0, feels = 0, wind = 0;
  int humidity = 0, code = 0;
  bool day = true;
  float hourTemp[kHours] = {};
  int8_t hourRain[kHours] = {};  // precipitation probability, %
  int hours = 0;
  float dayMax[kDays] = {}, dayMin[kDays] = {};
  int dayCode[kDays] = {};
  int days = 0;
};

// The scenes the screen can animate (and the AI may pick from).
enum class Scene : uint8_t { Sun, Clouds, Rain, Snow, Storm, Fog, Night };

namespace weather {

// WMO weather interpretation codes, as Open-Meteo reports them.
inline const char *describe(int code) {
  switch (code) {
    case 0: return "clear sky";
    case 1: return "mainly clear";
    case 2: return "partly cloudy";
    case 3: return "overcast";
    case 45: case 48: return "fog";
    case 51: case 53: case 55: return "drizzle";
    case 56: case 57: return "freezing drizzle";
    case 61: return "light rain";
    case 63: return "rain";
    case 65: return "heavy rain";
    case 66: case 67: return "freezing rain";
    case 71: case 73: case 75: case 77: return "snow";
    case 80: case 81: case 82: return "rain showers";
    case 85: case 86: return "snow showers";
    case 95: return "thunderstorm";
    case 96: case 99: return "thunderstorm, hail";
    default: return "unknown";
  }
}

inline Scene sceneFor(int code, bool day) {
  if (code >= 95) return Scene::Storm;
  if ((code >= 71 && code <= 77) || code == 85 || code == 86) return Scene::Snow;
  if (code >= 51) return Scene::Rain;
  if (code == 45 || code == 48) return Scene::Fog;
  if (code >= 2) return Scene::Clouds;
  return day ? Scene::Sun : Scene::Night;
}

inline const char *sceneName(Scene s) {
  static const char *const names[] = {"sun", "clouds", "rain", "snow", "storm", "fog", "night"};
  return names[static_cast<int>(s)];
}

inline bool sceneFromName(const char *name, Scene &out) {
  for (int i = 0; i <= static_cast<int>(Scene::Night); i++) {
    if (strcmp(name, sceneName(static_cast<Scene>(i))) == 0) {
      out = static_cast<Scene>(i);
      return true;
    }
  }
  return false;
}

inline HttpsResult geocode(const String &city, Place &out) {
  HttpsResult r = https::get("https://geocoding-api.open-meteo.com/v1/search?count=1&language=en&format=json&name=" +
                             https::urlEncode(city));
  if (!r.ok()) return r;
  JsonDocument doc;
  if (DeserializationError e = deserializeJson(doc, r.body)) {
    r.error = String("bad JSON: ") + e.c_str();
    return r;
  }
  JsonObjectConst hit = doc["results"][0];
  if (hit.isNull()) {
    r.error = "no place called '" + city + "'";
    return r;
  }
  out.name = String(hit["name"] | "?") + ", " + String(hit["country"] | "");
  out.lat = hit["latitude"] | 0.0f;
  out.lon = hit["longitude"] | 0.0f;
  return r;
}

inline HttpsResult fetch(const Place &place, Weather &out) {
  char url[400];
  snprintf(url, sizeof(url),
           "https://api.open-meteo.com/v1/forecast?latitude=%.4f&longitude=%.4f&timezone=auto"
           "&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,is_day"
           "&hourly=temperature_2m,precipitation_probability&forecast_hours=24"
           "&daily=weather_code,temperature_2m_max,temperature_2m_min&forecast_days=7",
           place.lat, place.lon);
  HttpsResult r = https::get(url);
  if (!r.ok()) return r;

  // A filter tells ArduinoJson which fields to keep. The time strings (the biggest part of the
  // answer) are dropped while parsing, so they never take up memory.
  JsonDocument filter;
  for (const char *k : {"temperature_2m", "apparent_temperature", "relative_humidity_2m", "weather_code",
                        "wind_speed_10m", "is_day"})
    filter["current"][k] = true;
  filter["hourly"]["temperature_2m"] = true;
  filter["hourly"]["precipitation_probability"] = true;
  filter["daily"]["weather_code"] = true;
  filter["daily"]["temperature_2m_max"] = true;
  filter["daily"]["temperature_2m_min"] = true;

  JsonDocument doc;
  if (DeserializationError e = deserializeJson(doc, r.body, DeserializationOption::Filter(filter))) {
    r.error = String("bad JSON: ") + e.c_str();
    return r;
  }
  JsonObjectConst now = doc["current"];
  if (now.isNull()) {
    r.error = "no current weather in the answer";
    return r;
  }
  Weather w;
  w.temp = now["temperature_2m"] | 0.0f;
  w.feels = now["apparent_temperature"] | 0.0f;
  w.humidity = now["relative_humidity_2m"] | 0;
  w.code = now["weather_code"] | 0;
  w.wind = now["wind_speed_10m"] | 0.0f;
  w.day = (now["is_day"] | 1) == 1;
  JsonArrayConst temps = doc["hourly"]["temperature_2m"], rain = doc["hourly"]["precipitation_probability"];
  for (size_t i = 0; i < temps.size() && w.hours < Weather::kHours; i++, w.hours++) {
    w.hourTemp[i] = temps[i] | 0.0f;
    w.hourRain[i] = int8_t(rain[i] | 0);
  }
  JsonArrayConst maxs = doc["daily"]["temperature_2m_max"], mins = doc["daily"]["temperature_2m_min"],
                 codes = doc["daily"]["weather_code"];
  for (size_t i = 0; i < maxs.size() && w.days < Weather::kDays; i++, w.days++) {
    w.dayMax[i] = maxs[i] | 0.0f;
    w.dayMin[i] = mins[i] | 0.0f;
    w.dayCode[i] = codes[i] | 0;
  }
  out = w;
  return r;
}

}  // namespace weather

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// Colour helpers for the 16-bit RGB565 format the ST7789 speaks: 5 bits red, 6 green, 5 blue.
#pragma once

#include <stdint.h>

constexpr uint16_t rgb(uint8_t r, uint8_t g, uint8_t b) {
  return uint16_t(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

// Hue 0-255 around the colour wheel, saturation and value 0-255.
inline uint16_t hsv(uint8_t h, uint8_t s, uint8_t v) {
  const uint8_t region = h / 43;
  const uint8_t rem = (h - region * 43) * 6;
  const uint8_t p = (v * (255 - s)) >> 8;
  const uint8_t q = (v * (255 - ((s * rem) >> 8))) >> 8;
  const uint8_t t = (v * (255 - ((s * (255 - rem)) >> 8))) >> 8;
  switch (region) {
    case 0: return rgb(v, t, p);
    case 1: return rgb(q, v, p);
    case 2: return rgb(p, v, t);
    case 3: return rgb(p, q, v);
    case 4: return rgb(t, p, v);
    default: return rgb(v, p, q);
  }
}

// Mix two colours: k = 0 gives a, k = 255 gives b.
inline uint16_t mix(uint16_t a, uint16_t b, uint8_t k) {
  const int ar = a >> 11, ag = (a >> 5) & 63, ab = a & 31;
  const int br = b >> 11, bg = (b >> 5) & 63, bb = b & 31;
  return uint16_t(((ar + ((br - ar) * k >> 8)) << 11) | ((ag + ((bg - ag) * k >> 8)) << 5) | (ab + ((bb - ab) * k >> 8)));
}

