// Our own off-screen picture, drawn with the normal Adafruit GFX calls.
//
// Lesson 03 used GFXcanvas16, which always lands in PSRAM (big but slow memory outside the chip).
// Here we choose: fast internal RAM when a big enough block is free, PSRAM otherwise.
// The serial log at start-up tells you which one you got.
#pragma once

#include <Adafruit_GFX.h>
#include <esp_heap_caps.h>

#include <algorithm>

class FrameBuffer : public Adafruit_GFX {
 public:
  FrameBuffer(int16_t w, int16_t h) : Adafruit_GFX(w, h) {}
  ~FrameBuffer() override { heap_caps_free(buf_); }

  bool begin() {
    const size_t bytes = bytesUsed();
    buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT));
    internal_ = buf_ != nullptr;
    if (buf_ == nullptr) buf_ = static_cast<uint16_t *>(heap_caps_malloc(bytes, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT));
    return buf_ != nullptr;
  }

  bool internal() const { return internal_; }
  size_t bytesUsed() const { return size_t(WIDTH) * HEIGHT * sizeof(uint16_t); }
  uint16_t *pixels() { return buf_; }

  // ---- The minimum Adafruit GFX needs (drawPixel) plus fast paths for lines and fills ----

  void drawPixel(int16_t x, int16_t y, uint16_t c) override {
    if (x < 0 || y < 0 || x >= _width || y >= _height) return;
    buf_[y * _width + x] = c;
  }

  void fillScreen(uint16_t c) override { std::fill_n(buf_, size_t(_width) * _height, c); }

  void drawFastHLine(int16_t x, int16_t y, int16_t w, uint16_t c) override {
    if (w < 0) x += w + 1, w = -w;
    if (y < 0 || y >= _height) return;
    if (x < 0) w += x, x = 0;
    if (x + w > _width) w = _width - x;
    if (w > 0) std::fill_n(buf_ + y * _width + x, w, c);
  }

  void drawFastVLine(int16_t x, int16_t y, int16_t h, uint16_t c) override {
    if (h < 0) y += h + 1, h = -h;
    if (x < 0 || x >= _width) return;
    if (y < 0) h += y, y = 0;
    if (y + h > _height) h = _height - y;
    for (uint16_t *p = buf_ + y * _width + x; h-- > 0; p += _width) *p = c;
  }

  void fillRect(int16_t x, int16_t y, int16_t w, int16_t h, uint16_t c) override {
    for (int16_t j = 0; j < h; j++) drawFastHLine(x, y + j, w, c);
  }

 private:
  uint16_t *buf_ = nullptr;
  bool internal_ = false;
};

// Wi-Fi scanning in the background.
//
// In station mode (STA) the ESP32 behaves like a phone or laptop. To scan, the radio hops
// through the 2.4 GHz channels. On each one it sends a "probe request" (who's there?)
// and listens for answers and for the "beacons" every router broadcasts about 10 times
// a second. Each answer carries the network name (SSID), the router's hardware address
// (BSSID), its channel and its security. We also measure how strong it arrived (RSSI, in dBm).
//
// scanNetworks(async = true) returns immediately, so the screen keeps animating while
// the Wi-Fi driver does the hopping on the other CPU core.
#pragma once

#include <WiFi.h>

#include <algorithm>
#include <vector>

struct ScanResult {
  String ssid;  // empty for hidden networks
  String bssid;
  int32_t rssi;  // dBm: -30 is very strong, -90 barely there
  uint8_t channel;
  wifi_auth_mode_t auth;
};

class Scanner {
 public:
  // Station mode, like a phone. Scanning also works while joined to a network:
  // the radio briefly visits the other channels, then comes back.
  void begin() { WiFi.mode(WIFI_STA); }

  // Start a scan unless one is already running. Hidden networks are included.
  bool start() {
    if (scanning_) return false;
    const int16_t r = WiFi.scanNetworks(/*async=*/true, /*show_hidden=*/true);
    if (r == WIFI_SCAN_FAILED) {
      log_e("Could not start a scan");
      return false;
    }
    scanning_ = true;
    startedAt_ = millis();
    return true;
  }

  // Call every loop. Returns true once, when a new set of results is ready.
  bool poll() {
    if (!scanning_) return false;
    const int16_t n = WiFi.scanComplete();
    if (n == WIFI_SCAN_RUNNING) return false;

    scanning_ = false;
    lastScanMs_ = millis() - startedAt_;
    networks_.clear();
    if (n < 0) {
      failed_ = true;
      log_e("Scan failed (code %d)", n);
      return true;
    }
    failed_ = false;
    for (int i = 0; i < n; i++) {
      networks_.push_back({WiFi.SSID(i), WiFi.BSSIDstr(i), WiFi.RSSI(i), uint8_t(WiFi.channel(i)), WiFi.encryptionType(i)});
    }
    WiFi.scanDelete();  // free the driver's copy; we keep ours
    std::sort(networks_.begin(), networks_.end(), [](const ScanResult &a, const ScanResult &b) { return a.rssi > b.rssi; });
    scans_++;
    finishedAt_ = millis();
    return true;
  }

  bool scanning() const { return scanning_; }
  bool failed() const { return failed_; }
  const std::vector<ScanResult> &networks() const { return networks_; }
  uint32_t lastScanMs() const { return lastScanMs_; }
  uint32_t scans() const { return scans_; }
  uint32_t finishedAt() const { return finishedAt_; }
  uint32_t elapsed() const { return millis() - startedAt_; }

 private:
  std::vector<ScanResult> networks_;
  bool scanning_ = false;
  bool failed_ = false;
  uint32_t startedAt_ = 0, finishedAt_ = 0, lastScanMs_ = 0, scans_ = 0;
};

// ---- Plain-language helpers ------------------------------------------------------------

inline const char *authName(wifi_auth_mode_t a) {
  switch (a) {
    case WIFI_AUTH_OPEN: return "open";
    case WIFI_AUTH_WEP: return "WEP";
    case WIFI_AUTH_WPA_PSK: return "WPA";
    case WIFI_AUTH_WPA2_PSK: return "WPA2";
    case WIFI_AUTH_WPA_WPA2_PSK: return "WPA/WPA2";
    case WIFI_AUTH_WPA2_ENTERPRISE: return "WPA2-Ent";
    case WIFI_AUTH_WPA3_PSK: return "WPA3";
    case WIFI_AUTH_WPA2_WPA3_PSK: return "WPA2/WPA3";
    case WIFI_AUTH_OWE: return "OWE";
    default: return "other";
  }
}

// 1-4 bars, the same rough scale phones use.
inline uint8_t signalBars(int32_t rssi) {
  if (rssi >= -55) return 4;
  if (rssi >= -67) return 3;
  if (rssi >= -78) return 2;
  return 1;
}

// One HTTPS request, the way a browser does it: look up the name, connect, check the server's
// certificate against the Mozilla root certificates built into the firmware, send, read the answer.
// Plain http:// works too (for a server on your own network, like the LiteLLM gateway on your Mac),
// but then nothing is encrypted or checked.
// Blocks until done (0.3 s to several seconds), so call it from a worker task, never from loop().
//
//   HttpsResult r = https::get("https://api.open-meteo.com/v1/forecast?...");
//   if (r.ok()) parse(r.body);
#pragma once

#include <HTTPClient.h>
#include <NetworkClientSecure.h>

#include <initializer_list>
#include <utility>

// The CA bundle ESP-IDF links into every firmware: the Mozilla root certificates, about 67 KB.
extern const uint8_t kHttpsCaBundleStart[] asm("_binary_x509_crt_bundle_start");
extern const uint8_t kHttpsCaBundleEnd[] asm("_binary_x509_crt_bundle_end");

struct HttpsResult {
  int status = 0;     // HTTP status, or a negative HTTPClient error (no network, TLS failed...)
  uint32_t ms = 0;    // whole request, including DNS, TCP and the TLS handshake
  size_t bytes = 0;   // size of the answer
  String body;
  String error;       // human-readable, empty on success
  bool ok() const { return status >= 200 && status < 300; }
};

namespace https {

using Header = std::pair<const char *, String>;

inline HttpsResult request(const char *method, const String &url, const String &body = "",
                           std::initializer_list<Header> headers = {}, uint16_t timeoutMs = 15'000) {
  HttpsResult r;
  const uint32_t start = millis();
  const bool secure = !url.startsWith("http://");
  NetworkClientSecure tls;
  NetworkClient plain;
  if (secure) tls.setCACertBundle(kHttpsCaBundleStart, kHttpsCaBundleEnd - kHttpsCaBundleStart);
  HTTPClient http;
  http.setConnectTimeout(8'000);
  http.setTimeout(timeoutMs);
  http.setReuse(false);  // one request per connection keeps memory use predictable
  if (!http.begin(secure ? static_cast<NetworkClient &>(tls) : plain, url)) {
    r.status = -1;
    r.error = "bad URL";
    return r;
  }
  for (const Header &h : headers) http.addHeader(h.first, h.second);
  r.status = http.sendRequest(method, body);
  if (r.status > 0) {
    r.body = http.getString();  // handles chunked answers too
    r.bytes = r.body.length();
    if (!r.ok()) r.error = "HTTP " + String(r.status);
  } else {
    r.error = HTTPClient::errorToString(r.status);  // e.g. "connection refused", "read Timeout"
  }
  http.end();
  r.ms = millis() - start;
  return r;
}

inline HttpsResult get(const String &url, std::initializer_list<Header> headers = {}) {
  return request("GET", url, "", headers);
}

inline HttpsResult post(const String &url, const String &body, std::initializer_list<Header> headers = {},
                        uint16_t timeoutMs = 15'000) {
  return request("POST", url, body, headers, timeoutMs);
}

// Make text safe inside a URL query: "São Paulo" -> "S%C3%A3o%20Paulo".
inline String urlEncode(const String &s) {
  String out;
  for (const uint8_t c : s) {
    if (isalnum(c) || c == '-' || c == '_' || c == '.' || c == '~') out += char(c);
    else {
      char hex[4];
      snprintf(hex, sizeof(hex), "%%%02X", c);
      out += hex;
    }
  }
  return out;
}

}  // namespace https
